use trustkit_orch::wave_board_dashboard_sse_client::{
    KanbanCardMutation, WaveBoardDashboardClient,
};

#[test]
fn test_task_005_red_phase_contract() {
    // Criterios: "Integracao Reativa do Dashboard Kanban Frontend com SSE"
    let mut client = WaveBoardDashboardClient::new();
    assert_eq!(client.card_count(), 0);

    let mutation1 = KanbanCardMutation {
        task_id: "TASK-005".to_string(),
        previous_column: "IN_PROGRESS".to_string(),
        new_column: "REVIEW".to_string(),
        tdd_phase: "GREEN".to_string(),
        timestamp_iso: "2026-11-17T15:00:00Z".to_string(),
    };
    client.apply_mutation(mutation1.clone());
    assert_eq!(client.card_count(), 1);

    let card = client.find_card("TASK-005").expect("Card should exist");
    assert_eq!(card.new_column, "REVIEW");
    assert_eq!(card.tdd_phase, "GREEN");

    let mutation2 = KanbanCardMutation {
        task_id: "TASK-005".to_string(),
        previous_column: "REVIEW".to_string(),
        new_column: "DONE".to_string(),
        tdd_phase: "GREEN".to_string(),
        timestamp_iso: "2026-11-17T15:05:00Z".to_string(),
    };
    client.apply_mutation(mutation2);
    assert_eq!(client.card_count(), 1);

    let card_updated = client.find_card("TASK-005").expect("Card should exist");
    assert_eq!(card_updated.new_column, "DONE", "GREEN verified");
}
